CREATE TABLE "public"."exercises" (
  "id"                bigint  GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."excercises_id_seq") NOT NULL,
  "exercise_name"     text    NOT NULL,
  "exercise_category" text,
  "is_library"        boolean DEFAULT true,
  "default_sets"      bigint,
  "default_reps"      bigint,
  "exercise_weight"   bigint,
  "exercise_notes"    text,
  "is_favorite"       boolean DEFAULT false,
  CONSTRAINT "excercises_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."exercises"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."workouts" (
  "id"               bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "workout_name"     text   NOT NULL,
  "workout_category" text,
  "workout_notes"    text,
  CONSTRAINT "workouts_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."workouts"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "allow anon read exercises" ON "public"."exercises"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."excercises_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."excercises_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."excercises_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."excercises_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."excercises_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."excercises_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."excercises_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."excercises_id_seq" TO "service_role";

REVOKE ALL ON SEQUENCE "public"."workouts_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."workouts_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."workouts_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."workouts_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."workouts_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."workouts_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."workouts_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."workouts_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."exercises" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."exercises" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."exercises" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."exercises" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workouts" TO "anon", "authenticated";

REVOKE ALL ON TABLE "public"."workouts" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workouts" TO "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."workouts" TO "service_role";

